typedef unsigned char u_char;

struct SpuStreamHeader {
    char id[4];
    int size;
    int type;
    int rate;
    int ch;
    int interSize;
    int loopStart;
    int loopEnd;
};
struct SpuStreamBody { char id[4]; int size; };
struct AudioDec {
    int state;
    SpuStreamHeader sshd;
    SpuStreamBody ssbd;
    int hdrCount;
    unsigned char *data;
    int put;
    int count;
    int size;
    int totalBytes;
    int iopBuff;
    int iopBuffSize;
    int iopLastPos;
    int iopPausePos;
    int totalBytesSent;
    int iopZero;
};

extern int sceSdRemote(int, int, ...);
extern void iopGetArea(int *, int *, int *, int *, AudioDec *, int);
extern int sendToIOP2area(int, int, int, int, u_char *, int, u_char *, int);

__asm__(".equ sceSdRemote, 0x0038BAE0");
__asm__(".equ iopGetArea__FPiN30P8AudioDeci, 0x00389A90");
__asm__(".equ sendToIOP2area__FiiiiPUciT4i, 0x00389B38");

#define AUTODMA_CH 0
#define UNIT_SIZE 1024
#define AU_STATE_INIT 0
#define AU_STATE_PRESET 1
#define AU_STATE_PLAY 2
#define AU_STATE_PAUSE 3
#define rSdBlockTransStatus 10
#define min(x,y) (((x) > (y)) ? (y) : (x))

int audioDecSendToIOP(AudioDec* ad)
{
    int     pd0, pd1, d0, d1, s0, s1, count_sent = 0, countAdj, pos = 0;
    u_char  *ps0, *ps1;

    switch( ad->state )
    {
    case AU_STATE_INIT  :
        return 0;
        break;
    case AU_STATE_PRESET:
        pd0 = ad->iopBuff + ( ad->totalBytesSent ) % ad->iopBuffSize;
        d0 = ad->iopBuffSize - ad->totalBytesSent;
        pd1 = 0;
        d1 = 0;
        break;
    case AU_STATE_PLAY  :
        pos = ( (sceSdRemote(1, rSdBlockTransStatus, AUTODMA_CH) & 0x00FFFFFF) - ad->iopBuff );
        iopGetArea( &pd0, &d0, &pd1, &d1, ad, pos );
        break;
    case AU_STATE_PAUSE :
        return 0;
        break;
    }

    ps0 = ad->data + ( ad->put - ad->count + ad->size ) % ad->size;
    ps1 = ad->data;
    countAdj = ( ad->count / UNIT_SIZE ) * UNIT_SIZE;
    s0 = min( ad->data + ad->size - ps0, countAdj );
    s1 = countAdj - s0;
    if( d0 + d1 >= UNIT_SIZE && s0 + s1 >= UNIT_SIZE )
    {
        count_sent = sendToIOP2area(pd0, d0, pd1, d1, ps0, s0, ps1, s1);
    }
    ad->count -= count_sent;
    ad->totalBytesSent += count_sent;
    ad->iopLastPos = ( ad->iopLastPos + count_sent ) % ad->iopBuffSize;
    return count_sent;
}
